// Query whether threading is supported/enabled on this build/platform.
// No inputs or persistent outputs are required.
bool ok = ILMTHREAD_INTERNAL_NAMESPACE::supportsThreads();
// Record globally for other stubs to gate thread ops if desired.
FUZZ_SET_ATTR_INT_GLOBAL("ilthread_support", ok ? 1 : 0);
// Validation: none beyond successful call; result cached globally for later gating.

// The base class is abstract; construct a minimal concrete subclass locally.
class FuzzThread final : public ILMTHREAD_INTERNAL_NAMESPACE::Thread {
public:
    void run() override {
        // Perform a tiny, fast, deterministic workload to keep join() quick.
        volatile unsigned int n = 16; // keep very small to avoid long runtimes
        for (volatile unsigned int i = 0; i < n; ++i) { /* no-op */ }
    }
};

// Construct a concrete thread object but do not start it yet.
ILMTHREAD_INTERNAL_NAMESPACE::Thread *thread = new FuzzThread();
// Track lifecycle and invariants for downstream stubs.
FUZZ_SET_ATTR_INT(thread, "is_concrete", 1);
FUZZ_SET_ATTR_INT(thread, "started", 0);
FUZZ_SET_ATTR_INT(thread, "joined", 0);

// Validation: object is non-null and marked concrete/unstarted for safe future start/join.

// Enforce that we only start concrete, not-yet-started threads and that threading is supported.
int concrete = FUZZ_GET_ATTR_INT(thread, "is_concrete");
if (!concrete) { FUZZ_BAIL(); }
int alreadyStarted = FUZZ_GET_ATTR_INT(thread, "started");
if (alreadyStarted) { FUZZ_BAIL(); }
int supportKnown = FUZZ_GET_ATTR_INT_GLOBAL("ilthread_support");
if (supportKnown == 0) {
    // If not cached, query now; if cached 0, threads unsupported -> bail.
    bool ok = ILMTHREAD_INTERNAL_NAMESPACE::supportsThreads();
    FUZZ_SET_ATTR_INT_GLOBAL("ilthread_support", ok ? 1 : 0);
    if (!ok) { FUZZ_BAIL(); }
} else if (supportKnown < 0) {
    // Negative is not used; treat as unsupported.
    FUZZ_BAIL();
}

// Start the thread; this will invoke run() on a new system thread.
thread->start();
FUZZ_SET_ATTR_INT(thread, "started", 1);
// We do not join here; leave it joinable for the join stub or destructor.

// Optional sanity check: a started thread should generally be joinable at some point.
// Do not assert here, since timing could make joinable() transiently false; just proceed.

// Validation: ensured concrete, single-start, and platform support before calling start().

// Ensure join() is only called on a started and not-yet-joined thread.
int concrete = FUZZ_GET_ATTR_INT(thread, "is_concrete");
if (!concrete) { FUZZ_BAIL(); }
int started = FUZZ_GET_ATTR_INT(thread, "started");
if (!started) { FUZZ_BAIL(); }
int alreadyJoined = FUZZ_GET_ATTR_INT(thread, "joined");
if (alreadyJoined) { FUZZ_BAIL(); }

// Optionally check joinable() precondition; if false, bail to avoid blocking undefined state.
bool preJoinable = thread->joinable();
if (!preJoinable) { FUZZ_BAIL(); }

// Join the thread; this should return quickly because run() is trivial.
thread->join();
FUZZ_SET_ATTR_INT(thread, "joined", 1);

// Post-condition: after join, the thread should not be joinable.
bool postJoinable = thread->joinable();
FUZZ_ASSERT(!postJoinable, "Thread must not be joinable after join()");

// Validation: guarded by started/not-joined and joinable() precheck; assert post-condition holds.

// Simply query joinable state; keep the object alive by returning it.
// This call must not alter ownership/lifetime.
(void)thread->joinable();

// Validation: no state changes; object returned to pool intact.

// Respect API guidance: join before deleting. Ensure we only operate on our concrete instances.
int concrete = FUZZ_GET_ATTR_INT(thread, "is_concrete");
if (!concrete) { FUZZ_BAIL(); }
int started = FUZZ_GET_ATTR_INT(thread, "started");
int joined = FUZZ_GET_ATTR_INT(thread, "joined");

// If the thread was started but not yet joined, join it now to fulfill the contract.
if (started && !joined) {
    if (!thread->joinable()) { FUZZ_BAIL(); }
    thread->join();
}

// Delete the object to invoke ~Thread() via the derived instance.
delete thread;

