import json
import random
import string
from typing import List, Tuple

# This generator creates valid UTF-8 JSON text suited for Imf::addAscFramingDecisionList
# The fuzz stubs sanitize to printable ASCII and expect compact JSON strings. We produce
# small, syntactically valid JSON objects/arrays with varying shapes while staying under 4096 bytes.

_PRINTABLE = string.ascii_letters + string.digits + string.punctuation + " "
_SAFE_ASCII = ''.join(ch for ch in _PRINTABLE if 32 <= ord(ch) <= 126 and ch not in ['\\', '"'])


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    # Prefer characters that will remain unchanged by stub's sanitization and minimal escaping
    # Avoid backslash and quote to reduce escaping, but allow occasionally for coverage
    base = _SAFE_ASCII
    s = ''.join(rng.choice(base) for _ in range(n))
    # Ensure non-empty and printable
    if not s:
        s = 'x'
    return s


def _rand_number(rng: random.Random):
    # Mix ints and floats
    if rng.random() < 0.6:
        # int range includes negatives and large magnitudes
        return rng.randint(-2**31, 2**31 - 1)
    else:
        # floats including special magnitudes; JSON doesn't support NaN/Inf, so avoid them
        # Generate with rounded precision
        val = (rng.random() * 2 - 1) * 1e6
        return float(round(val, rng.randint(0, 6)))


def _rand_bool(rng: random.Random):
    return bool(rng.getrandbits(1))


def _rand_scalar(rng: random.Random):
    t = rng.random()
    if t < 0.4:
        return _rand_ascii(rng, 1, 32)
    elif t < 0.7:
        return _rand_number(rng)
    elif t < 0.9:
        return _rand_bool(rng)
    else:
        return None  # null in JSON


def _rand_key(rng: random.Random):
    # Keys are strings; keep short to match stub truncations
    return _rand_ascii(rng, 1, 16)


def _make_object(rng: random.Random, depth: int) -> dict:
    obj = {}
    # between 1 and 6 entries
    count = rng.randint(1, 6)
    for _ in range(count):
        key = _rand_key(rng)
        # Ensure unique keys
        attempt = 0
        while key in obj and attempt < 5:
            key = _rand_key(rng)
            attempt += 1
        # Decide value type
        v_pick = rng.random()
        if depth < 2 and v_pick < 0.25:
            val = _make_object(rng, depth + 1)
        elif depth < 2 and v_pick < 0.45:
            val = _make_array(rng, depth + 1)
        else:
            val = _rand_scalar(rng)
        obj[key] = val
    return obj


def _make_array(rng: random.Random, depth: int) -> list:
    arr = []
    count = rng.randint(1, 6)
    for _ in range(count):
        v_pick = rng.random()
        if depth < 2 and v_pick < 0.2:
            arr.append(_make_object(rng, depth + 1))
        elif depth < 2 and v_pick < 0.35:
            arr.append(_make_array(rng, depth + 1))
        else:
            arr.append(_rand_scalar(rng))
    return arr


def _random_json_root(rng: random.Random):
    # Stubs typically construct {"k":"v"}; prioritize objects but include arrays sometimes
    if rng.random() < 0.75:
        return _make_object(rng, 0)
    else:
        return _make_array(rng, 0)


def _compact_dumps(obj) -> str:
    # Compact JSON to stay small
    return json.dumps(obj, ensure_ascii=True, separators=(",", ":"))


def _trim_to_limit(s: str, limit: int) -> str:
    if len(s) <= limit:
        return s
    # If too long, try simplifying by reducing depth: convert to a simple object with a few kv pairs
    # This maintains validity and increases chance of being preserved by stub truncations.
    try:
        return _compact_dumps({"k": "v", "n": 1, "ok": True})[:limit]
    except Exception:
        return s[:limit]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose one of several schema variants typical for ASC framing decision list representations
    # but keep generic since stubs only require syntactically valid JSON.
    variant = rng.randint(0, 5)

    if variant == 0:
        # Simple single key-value object
        k = _rand_key(rng)
        v = _rand_ascii(rng, 1, 64)
        obj = {k: v}
        payload = _compact_dumps(obj)
    elif variant == 1:
        # Object with mixed scalar types
        obj = {
            _rand_key(rng): _rand_ascii(rng, 1, 32),
            _rand_key(rng): _rand_number(rng),
            _rand_key(rng): _rand_bool(rng),
            _rand_key(rng): None,
        }
        payload = _compact_dumps(obj)
    elif variant == 2:
        # Nested object
        obj = {
            _rand_key(rng): {
                _rand_key(rng): _rand_ascii(rng, 1, 32),
                _rand_key(rng): _rand_number(rng),
            },
            _rand_key(rng): _rand_bool(rng),
        }
        payload = _compact_dumps(obj)
    elif variant == 3:
        # Array of objects
        arr = []
        for _ in range(rng.randint(1, 4)):
            arr.append({
                _rand_key(rng): _rand_ascii(rng, 1, 24),
                _rand_key(rng): _rand_number(rng),
            })
        payload = _compact_dumps(arr)
    elif variant == 4:
        # Fully random object/array via generators
        root = _random_json_root(rng)
        payload = _compact_dumps(root)
    else:
        # Typical framing-like structure with known fields to encourage library code paths
        obj = {
            "name": _rand_ascii(rng, 3, 16),
            "version": _rand_ascii(rng, 1, 8),
            "active": _rand_bool(rng),
            "params": {
                "width": int(abs(_rand_number(rng))) % 100000 or 1,
                "height": int(abs(_rand_number(rng))) % 100000 or 1,
                "aspect": float(max(0.1, abs(_rand_number(rng)) % 10.0)),
            },
        }
        payload = _compact_dumps(obj)

    # Ensure non-empty and compact; stubs may truncate, so keep payload modest.
    payload = _trim_to_limit(payload, 256)
    if not payload:
        payload = '{"k":"v"}'

    # Return UTF-8 bytes
    data = payload.encode('utf-8')
    # Safety: ensure <= 4096 bytes
    if len(data) > 4096:
        data = data[:4096]
    return data
